## Why This Is Asked

This question probes offline-first real-time collaboration with WebSocket, fetch, and service workers, focusing on delivery guarantees, reconciliation, and DOM performance.

## Key Concepts
- WebSocket reliability and reconnection strategies
- Offline event queue, idempotent replay, and sequence numbering
- Conflict resolution via CRDT/OT for drawing data
- Service Worker caching and fetch semantics (ETag, conditional requests)
- DOM rendering optimization for high-frequency updates (offscreen/virtual canvas, requestAnimationFrame)
- Data modeling for strokes: path data, layer IDs, sequence numbers

## Code Example
```javascript
let pending = [];
let lastSeq = 0;
function onStroke(stroke){
  const e = {id: stroke.id, seq: ++lastSeq, data: stroke};
  pending.push(e);
  ws.send(JSON.stringify(e));
}
function onReconnect(){
  ws.onopen = ()=>{ pending.forEach(e=> ws.send(JSON.stringify(e))); };
}
```

## Follow-up Questions
- How would you handle limited bandwidth and out-of-order messages?
- How would you persist unsent changes across tab closures?

## Why This Is Asked

Assess practical CSS grid skills, responsive breakpoints, and accessible motion. The candidate must show how to implement a non-shifting overlay reveal using absolute positioning and transform, with clean fallbacks for users who disable motion.

## Key Concepts

- CSS Grid with explicit breakpoints and repeat()
- aspect-ratio for poster sizing
- overlay reveal via transform to avoid CLS
- focus-visible and prefers-reduced-motion
- nested flexbox for caption alignment

## Code Example

```css
.grid{ display:grid; grid-template-columns: repeat(5, 1fr); gap:16px; }
@media (max-width:1200px){ .grid{ grid-template-columns: repeat(3, 1fr);} }
@media (max-width:900px){ .grid{ grid-template-columns: repeat(2, 1fr);} }
.card{ position:relative; height:260px; overflow:hidden; }
.poster{ width:100%; height:100%; object-fit:cover; aspect-ratio:16/9; display:block; }
.overlay{ position:absolute; left:0; right:0; bottom:0; padding:12px; background: rgba(0,0,0,.6); color:#fff; transform: translateY(100%); opacity:0; transition: transform .25s, opacity .25s; }
.card:hover .overlay, .card:focus-within .overlay{ transform: translateY(0); opacity:1; }
@media (prefers-reduced-motion: reduce){ .overlay{ transition:none; } }
```

## Follow-up Questions

- How would you adapt this pattern to support keyboard-only navigation without visual jitter?
- What accessibility tests would you run to ensure the overlay remains readable on all devices?

## Why This Is Asked
This question tests the ability to design an offline-first, real-time collaboration feature using the Canvas API, WebSocket communication, and Service Workers. It evaluates understanding of robust reconnection strategies, multi-client synchronization, and cross-tab coordination.

## Key Concepts
- Canvas rendering with minimal DOM manipulation; use a single render loop via requestAnimationFrame
- WebSocket-based real-time synchronization with an operation log and CRDT-like merge logic
- Service Worker caching for the app shell and board bitmap to enable offline use
- Cross-tab coordination via BroadcastChannel with resilient reconnect and exponential backoff strategies

## Code Example
```javascript
// WebSocket wrapper (connect, backoff, send, onMessage)
class WS {
  constructor(url) {
    this.url = url;
    this.ws = null;
    this.reconnectDelay = 1000;
    this.maxReconnectDelay = 30000;
    this.handlers = {};
  }

  connect() {
    this.ws = new WebSocket(this.url);
    this.ws.onopen = () => { this.reconnectDelay = 1000; };
    this.ws.onclose = () => this.reconnect();
    this.ws.onmessage = (e) => {
      const msg = JSON.parse(e.data);
      this.handlers[msg.type]?.(msg.payload);
    };
  }

  reconnect() {
    setTimeout(() => {
      this.reconnectDelay = Math.min(this.reconnectDelay * 2, this.maxReconnectDelay);
      this.connect();
    }, this.reconnectDelay);
  }

  send(type, payload) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(JSON.stringify({ type, payload }));
    }
  }

  on(type, handler) {
    this.handlers[type] = handler;
  }
}

// opLog for CRDT-like merge
class OpLog {
  constructor() {
    this.ops = [];
    this.vectorClock = {};
  }

  addOp(op) {
    this.ops.push(op);
    this.vectorClock[op.clientId] = (this.vectorClock[op.clientId] || 0) + 1;
  }

  merge(remoteOps) {
    for (const op of remoteOps) {
      const dominated = this.ops.some(local =>
        local.clientId === op.clientId && local.timestamp <= op.timestamp
      );
      if (!dominated) {
        this.ops.push(op);
      }
    }
  }
}

// Service Worker (install/activate/cache)
// sw.js
self.addEventListener('install', (e) => {
  e.waitUntil(
    caches.open('whiteboard-v1').then(cache => cache.addAll(['/', '/index.html', '/app.js']))
  );
  self.skipWaiting();
});

self.addEventListener('activate', (e) => {
  e.waitUntil(
    caches.keys().then(keys =>
      Promise.all(keys.filter(k => k !== 'whiteboard-v1').map(k => caches.delete(k)))
    )
  );
  self.clients.claim();
});

self.addEventListener('fetch', (e) => {
  e.respondWith(
    caches.match(e.request).then(cached => cached || fetch(e.request))
  );
});

// Main render wiring
const canvas = document.getElementById('board');
const ctx = canvas.getContext('2d');
const ws = new WS('ws://localhost:8080');
const opLog = new OpLog();

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const op of opLog.ops) {
    ctx.beginPath();
    ctx.moveTo(op.x1, op.y1);
    ctx.lineTo(op.x2, op.y2);
    ctx.stroke();
  }
  requestAnimationFrame(render);
}

canvas.addEventListener('mousemove', (e) => {
  if (e.buttons !== 1) return;
  const op = { x1: lastX, y1: lastY, x2: e.offsetX, y2: e.offsetY };
  opLog.addOp(op);
  ws.send('stroke', op);
  lastX = e.offsetX;
  lastY = e.offsetY;
});

ws.on('stroke', (op) => opLog.addOp(op));
ws.connect();
render();
```

## Why This Is Asked
Tests cross-tenant state management, React performance optimization, and integration with existing Redux-like architectures.

## Key Concepts
- useSyncExternalStore for external state subscriptions
- Tenant-isolated caching with Map-based storage
- Memoized selectors to prevent unnecessary re-renders
- React.memo and useTransition for smooth UI updates
- SSR-safe defaults and hydration patterns
- Proper cleanup on tenant switching

## Code Example
```javascript
// useFlag hook implementation
export function useFlag(flagName) {
  const tenant = useContext(TenantContext)
  const flagStore = useFlagStore()

  return useSyncExternalStore(
    (onStoreChange) => flagStore.subscribe(tenant.id, flagName, onStoreChange),
    () => flagStore.getFlag(tenant.id, flagName),
    () => flagStore.getFlag(tenant.id, flagName) // SSR fallback
  )
}
```

