// Skeleton: connect, batch render, offline queue
class DashboardClient {
  constructor() {
    this.state = { widgets: [] }
    this.queue = []
    this.renderScheduled = false
  }
  connect() {
    this.ws = new WebSocket('wss://example/live')
    this.ws.onmessage = e => {
      const d = JSON.parse(e.data)
      this.state.widgets = merge(this.state.widgets, d)
      this.scheduleRender()
    }
  }
  scheduleRender() {
    if (this.renderScheduled) return
    this.renderScheduled = true
    requestIdleCallback(() => { this.render(); this.renderScheduled = false })
  }
  render() {
    // update DOM from this.state
  }
  queueOfflineEdit(edit) {
    // store in IndexedDB
  }
  flushQueue() {
    // retry edits when online or ws reconnects
  }
}
```

